1.query:
// Recurrence: Davis problems per runtime unit per day.
// Unit = Kubernetes workload, else process group, else host. Service problems roll up to the unit the service runs in.
fetch dt.davis.problems, from: now()-30d
| filter dt.davis.is_duplicate == false
| expand id = affected_entity_ids
| summarize { start = min(event.start), title = takeFirst(event.name) }, by: { display_id, id = toString(id) }
| fieldsAdd kind = substring(id, from: 0, to: indexOf(id, "-"))
// Services and process instances become the process instances they run in.
| lookup [
    fetch dt.entity.service, from: now()-30d
    | fields sid = toString(id), pgis = runs_on[dt.entity.process_group_instance]
  ], sourceField: id, lookupField: sid, fields: { pgis }
| fieldsAdd pgis = if(kind == "PROCESS_GROUP_INSTANCE", array(id), else: pgis)
| fieldsAdd pgis = coalesce(pgis, array(""))
| expand pgi = pgis
| fieldsAdd pgi = toString(pgi)
| lookup [
    smartscapeNodes PROCESS, from: now()-30d
    | fields pgi = id_classic, process_id = toString(id), pg_name = dt.process_group.detected_name
  ], sourceField: pgi, lookupField: pgi, fields: { process_id, pg_name }
| lookup [
    smartscapeEdges runs_on, from: now()-30d
    | filter source_type == "PROCESS" and target_type == "CONTAINER"
    | fields process_id = toString(source_id), container_id = toString(target_id)
  ], sourceField: process_id, lookupField: process_id, fields: { container_id }
| lookup [
    smartscapeEdges is_part_of, from: now()-30d
    | filter source_type == "CONTAINER" and target_type == "K8S_POD"
    | fields container_id = toString(source_id), pod_id = toString(target_id)
  ], sourceField: container_id, lookupField: container_id, fields: { pod_id }
| lookup [
    smartscapeNodes K8S_POD, from: now()-30d
    | fields pod_id = toString(id), pod_workload = k8s.workload.name, pod_ns = k8s.namespace.name
  ], sourceField: pod_id, lookupField: pod_id, fields: { pod_workload, pod_ns }
// Problems raised on the workload itself.
| lookup [
    fetch dt.entity.cloud_application, from: now()-30d
    | fields cid = toString(id), ca_name = entity.name, ca_ns = namespaceName
  ], sourceField: id, lookupField: cid, fields: { ca_name, ca_ns }
| fieldsAdd host_name = if(kind == "HOST", entityName(id, type: "dt.entity.host"))
| fieldsAdd unit = coalesce(
    if(isNotNull(pod_workload), concat("k8s · ", pod_ns, "/", pod_workload)),
    if(isNotNull(ca_name), concat("k8s · ", ca_ns, "/", ca_name)),
    if(isNotNull(pg_name), concat("process · ", pg_name)),
    if(isNotNull(host_name), concat("host · ", host_name)))
| filter isNotNull(unit)
| makeTimeseries problems = countDistinct(display_id), by: { unit }, time: start, interval: 1d, from: now()-30d, to: now()
| fieldsAdd total = arraySum(problems)
| sort total desc
| limit 25
| fields timeframe, interval, unit, problems

3.query:
// Recurrence: process crashes/restarts per runtime unit per day.
// Event type differs per tenant (PROCESS_RESTART or PGI_CRASHED_INFO), so both are read.
fetch dt.davis.events, from: now()-30d
| filter in(event.type, "PROCESS_RESTART", "PGI_CRASHED_INFO")
| fields timestamp, pgi = toString(dt.source_entity)
| lookup [
    smartscapeNodes PROCESS, from: now()-30d
    | fields pgi = id_classic, process_id = toString(id), pg_name = dt.process_group.detected_name
  ], sourceField: pgi, lookupField: pgi, fields: { process_id, pg_name }
// Aggregate pseudo-groups, not applications.
| filter isNotNull(pg_name) and not in(pg_name, "Short-lived processes", "Linux System")
| lookup [
    smartscapeEdges runs_on, from: now()-30d
    | filter source_type == "PROCESS" and target_type == "CONTAINER"
    | fields process_id = toString(source_id), container_id = toString(target_id)
  ], sourceField: process_id, lookupField: process_id, fields: { container_id }
| lookup [
    smartscapeEdges is_part_of, from: now()-30d
    | filter source_type == "CONTAINER" and target_type == "K8S_POD"
    | fields container_id = toString(source_id), pod_id = toString(target_id)
  ], sourceField: container_id, lookupField: container_id, fields: { pod_id }
| lookup [
    smartscapeNodes K8S_POD, from: now()-30d
    | fields pod_id = toString(id), pod_workload = k8s.workload.name, pod_ns = k8s.namespace.name
  ], sourceField: pod_id, lookupField: pod_id, fields: { pod_workload, pod_ns }
| fieldsAdd unit = coalesce(if(isNotNull(pod_workload), concat("k8s · ", pod_ns, "/", pod_workload)), concat("process · ", pg_name))
| makeTimeseries crashes = count(), by: { unit }, interval: 1d, from: now()-30d, to: now()
| fieldsAdd total = arraySum(crashes)
| sort total desc
| limit 25
| fields timeframe, interval, unit, crashes

